// Bundles knowledge/seed/<tenant>/* into a TS module so serverless functions don't read files at runtime.
import fs from "node:fs";
import path from "node:path";
const root = "knowledge/seed";
const out = {};
for (const tenant of fs.readdirSync(root)) {
  const dir = path.join(root, tenant);
  if (!fs.statSync(dir).isDirectory()) continue;
  const docs = fs.readdirSync(dir).filter((f) => f.endsWith(".md")).sort().map((f) => ({ file: f, raw: fs.readFileSync(path.join(dir, f), "utf8") }));
  const websiteFile = path.join(dir, "website.json");
  out[tenant] = { docs, website: fs.existsSync(websiteFile) ? JSON.parse(fs.readFileSync(websiteFile, "utf8")) : null };
}
fs.mkdirSync("server/generated", { recursive: true });
fs.writeFileSync("server/generated/seed-bundle.ts", `// GENERATED by scripts/build-seed-bundle.mjs — do not edit.\nexport const SEED_BUNDLE: Record<string, { docs: { file: string; raw: string }[]; website: Record<string, unknown> | null }> = ${JSON.stringify(out, null, 1)};\n`);
console.log("seed bundle:", Object.entries(out).map(([k, v]) => `${k}=${v.docs.length} docs`).join(", "));
